# Generated by manage.py generate_test_cases.
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.conferencing.sharing_fixtures import SharingFixtures


class TestGuestJoinComponent(SharingFixtures, BloomerpComponentTestCase):
    view_name = "components_conferencing_guest_join"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover browser identity and host-only admission at the routed boundary."""
        return [
            RequestScenario(
                name="A link alone cannot issue credentials",
                method="POST",
                prepare=self.prepare_link,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Authenticated members must also request admission via a link",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_link,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="GET never issues credentials",
                prepare=self.prepare_link,
                expected=ExpectedResult(status_code=405),
            ),
        ]

    def test_anonymous_admission_lifecycle(self) -> None:
        """Use case: Anonymous link visitor. Expected: host admission and browser binding gate media."""
        self.exercise_lifecycle(False)

    def test_account_admission_lifecycle(self) -> None:
        """Use case: Account link visitor. Expected: account identity still waits for host approval."""
        self.exercise_lifecycle(True)

    def exercise_lifecycle(self, authenticated: bool) -> None:
        """Exercise cookie-bound requests, host decisions, signed credentials and webhook retention."""
        import jwt
        from django.test import Client
        from django.urls import reverse

        from bloomerp.communication.builtins.conferencing.controller import (
            ConferenceController,
        )
        from bloomerp.communication.builtins.conferencing.webhooks import (
            reconcile_event,
        )
        from bloomerp.models.communication.conferencing import ConferenceAdmission

        self.prepare_session()
        visitor = Client(enforce_csrf_checks=True)
        if authenticated:
            visitor.force_login(self.admin_user)
        token_kwargs = {"token": self.session.share_token}
        page = reverse("conference_sessions_meeting", kwargs=token_kwargs)
        self.assertEqual(visitor.get(page).status_code, 200)
        csrf = visitor.cookies["csrftoken"].value
        ask = reverse("components_conferencing_request_admission", kwargs=token_kwargs)
        join = reverse("components_conferencing_guest_join", kwargs=token_kwargs)
        self.assertEqual(visitor.post(ask, {"name": "Guest"}).status_code, 403)
        self.assertEqual(
            visitor.post(ask, {"name": "Guest"}, HTTP_X_CSRFTOKEN=csrf).status_code, 200
        )
        self.assertEqual(
            visitor.post(ask, {"name": "Changed"}, HTTP_X_CSRFTOKEN=csrf).status_code,
            200,
        )
        admission = ConferenceAdmission.objects.get(session=self.session)
        self.assertEqual(
            admission.display_name,
            (self.admin_user.get_full_name() or str(self.admin_user))
            if authenticated
            else "Guest",
        )
        self.assertEqual(visitor.post(join, HTTP_X_CSRFTOKEN=csrf).status_code, 403)
        self.client.force_login(self.normal_user)
        decide = reverse(
            "components_conferencing_decide_admission",
            kwargs={"session_id": self.session.pk, "admission_id": admission.pk},
        )
        self.assertEqual(
            self.client.post(decide, {"decision": "admit"}).status_code, 200
        )
        response = visitor.post(join, HTTP_X_CSRFTOKEN=csrf)
        self.assertEqual(response.status_code, 200)
        payload = response.json()
        claims = jwt.decode(
            payload["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        self.assertEqual(claims["name"], admission.display_name)
        self.assertEqual(payload["can_end"], "false")
        self.assertNotIn("admissions_url", payload)
        stranger = Client()
        if authenticated:
            stranger.force_login(self.admin_user)
        self.assertEqual(stranger.post(join).status_code, 403)
        reconcile_event(
            self.connection_event("guest-joined", "participant_joined", claims["sub"])
        )
        self.remove_participant.assert_not_called()
        admission.refresh_from_db()
        self.assertEqual(admission.participant.attendances.count(), 1)
        self.assertEqual(self.chat.participants.count(), 2)
        ConferenceController(self.normal_user).end(self.session.pk)
        self.assertEqual(visitor.post(join, HTTP_X_CSRFTOKEN=csrf).status_code, 404)
        self.assertEqual(visitor.get(page).status_code, 404)
